// include/reward/verifiers/Verifier.h
class Verifier {
 public:
  virtual ScoreResult score(const std::string& response,
                            const std::string& ground_truth) = 0;
  virtual ScoreResult score_trajectory(const TrajectoryData& t) {
    return score(t.response_text, t.ground_truth);
  }
};
// shared by every reward thread: score() must be
// safe to call concurrently (no mutable state)

